function liquidate(uint id, uint to, uint repayAmount, address recipient) external isValidDNft(id) isValidDNft(to) {
    if (msg.sender == tokenOwner[id]) revert SelfLiquidation();
    uint cr = collatRatio(id);
    if (cr >= MIN_COLLATERIZATION_RATIO) revert CrTooHigh();
    dyad.burn(id, msg.sender, repayAmount);

    uint cappedCr = cr < 1e18 ? 1e18 : cr;
    uint liquidationEquityShare = (cappedCr - 1e18).mulWadDown(LIQUIDATION_REWARD);
    uint liquidationAssetShare = (liquidationEquityShare + 1e18).divWadDown(cappedCr);

    uint totalCollateral = 0;
    for (uint i = 0; i < vaults[id].length(); i++) {
        Vault vault = Vault(vaults[id].at(i));
        totalCollateral += vault.id2asset(id);
    }
    for (uint i = 0; i < vaultsKerosene[id].length(); i++) {
        Vault vault = Vault(vaultsKerosene[id].at(i));
        totalCollateral += vault.id2asset(id);
    }
    for (uint i = 0; i < vaults[id].length(); i++) {
        Vault vault = Vault(vaults[id].at(i));
        uint collateral = vault.id2asset(id).mulWadUp(liquidationAssetShare);
        vault.move(id, to, collateral);
    }
    for (uint i = 0; i < vaultsKerosene[id].length(); i++) {
        Vault vault = Vault(vaultsKerosene[id].at(i));
        uint collateral = vault.id2asset(id).mulWadUp(liquidationAssetShare);
        vault.move(id, to, collateral);
    }
    dailyDebtIncreaseLimitLeft += repayAmount;
    emit Liquidate(id, msg.sender, to, recipient, repayAmount);
}
